// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용

scwin.vIsurCd;
scwin.getPar, scwin.setPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_Item);
        const parentWin = $c.frame.path("../");
        scwin.vIsurCd = parentWin.txb_ISUR_CD.getValue();
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92021.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Dscl_onclick
 * @description 「안내문작성」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Dscl_onclick = async function() {
    try {
        await scwin.dscl();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92021.btn_Dscl_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92021.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name grd_IssRecv_OnClick
 * @description grd_IssRecv 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_IssRecv_OnClick = async function(row, colid) {
    try {
        await scwin.openDetail(row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92021.grd_IssRecv_OnClick" });
    }
};

