};

/**
 * @method
 * @name dscl
 * @description dscl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dscl = async function() {
    const vRsnCd = dts_IssRecv.getCellData(dts_IssRecv.getRowPosition(), "STK_ISU_RSN_CD");
    const vListDD = dts_IssRecv.getCellData(dts_IssRecv.getRowPosition(), "LIST_DD");
    const vMethdTpCd = dts_IssRecv.getCellData(dts_IssRecv.getRowPosition(), "LIST_METHD_TP_CD");

    // var vBzProcsNo = dts_IssList.NameString(dts_IssList.RowPosition, "BZ_PROCS_NO");
    let vBzProcsNo = "";
    for (let i = 1; i <= dts_IssList.getRowCount(); i++) {
        vBzProcsNo = vBzProcsNo + (vBzProcsNo === "" ? "" : ",") + dts_IssList.getCellData(i, "BZ_PROCS_NO");
    }
    if (vRsnCd === "" || vBzProcsNo === "") {
        await $c.win.alert("[대상]을 선택하세요.");
        return;
    }
    /*
    if(  dts_Mst.IsUpdated || dts_Isu.IsUpdated || dts_Rsn.IsUpdated ) {
    	alert(getMessageParam("MSG-0022", ""));
    	return ;
    }
    alert("vRsnCd."+vRsnCd)
    alert("vListDD."+vListDD)
    alert("vBzProcsNo."+vBzProcsNo)
     */
    let rsnKey = scwin.getRsnCse(vRsnCd);
    const OldGet = scwin.getPar;
    const OldSet = scwin.setPar;

    // 우선주의보통주전환사유 변경상장,추가상장 둘다 존재(2017.05.18)
    if (vRsnCd === '625') {
        if (vMethdTpCd === '2') {
            // 추가상장
            rsnKey = '130';
        } else if (vMethdTpCd === '3') {
            // 변경상장
            rsnKey = '141';
        }
    }

    // alert("발행사유코드 -->"+rsnKey + " vRsnCd:" + vRsnCd);

    if (rsnKey === "148") {
        // 상호변경
        const sbmOptions = {
            id : "sbm_dts_DsclMst",
            action : "/Listing.do",
            ref : "",
            target : "dts_DsclMst=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        /* 2009.05.22 영문공시 추가 */
        const sbmOptions2 = {
            id : "sbm_dts_DsclMst_Eng",
            action : "/Listing.do",
            ref : "",
            target : "dts_DsclMst_Eng=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        let dBzProcsNo = vBzProcsNo;
        for (let i = 1; i <= dts_DsclMst.getRowCount(); i++) {
            dBzProcsNo = dBzProcsNo + (dBzProcsNo === "" ? "" : ",") + dts_DsclMst.getCellData(i, "BZ_PROCS_NO");
        }
        /*
        fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        	arr[0] = "70765";
        	arr[1] = vBzProcsNo;
        	arr[2] = vIsurCd;
            //CopyDataSet( dts_Delistdetail , param_dts_isu) ;
        	CopyDataSet( dts_DsclMst, param_dts_mst) ;
        	CopyDataSet( dts_IssList, param_dts2) ;
        	return arr.length;
        }
         */
        // fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3,  param_dts_mst_eng) {
        scwin.getPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3, param_dts4, param_dts_isu_eng, param_dts_mst_eng, param_dts_dtl_eng, param_dts_dtl_all_eng, param_dts_rel_eng) {
            if (js_market === "2") {
                arr[0] = "70765";
            } else {
                // 코넥스
                arr[0] = "32005";
            }
            arr[1] = dBzProcsNo;
            arr[2] = scwin.vIsurCd;
            $c.stf.copyDataSet(dts_DsclMst, param_dts_mst);
            $c.stf.copyDataSet(dts_IssList, param_dts2);
            $c.stf.copyDataSet(dts_DsclMst_Eng, param_dts_mst_eng);
            $c.stf.copyDataSet(dts_IssList_Eng, param_dts_dtl_eng);
            return arr.length;
        };
    } else if (rsnKey === "141A") {
        // 액면변경
        const sbmOptions = {
            id : "sbm_dts_DsclMst",
            action : "/Listing.do",
            ref : "",
            target : "dts_DsclMst=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions2 = {
            id : "sbm_dts_DsclDtl",
            action : "/Listing.do",
            ref : "",
            target : "dts_DsclDtl=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        /* 2009.06.03 영문공시 추가 */
        const sbmOptions3 = {
            id : "sbm_dts_DsclMst_Eng",
            action : "/Listing.do",
            ref : "",
            target : "dts_DsclMst_Eng=body.content",
            isProcessMsg : false
        };

        const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
        // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions4 = {
            id : "sbm_dts_DsclDtl_Eng",
            action : "/Listing.do",
            ref : "",
            target : "dts_DsclDtl_Eng=body.content",
            isProcessMsg : false
        };

        const sbmRtn4 = await $c.sbm.executeDynamic(sbmOptions4);
        // TODO Stage2: sbmRtn4 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        /*
        fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        	arr[0] = "70764";
        	arr[1] = vBzProcsNo ;
        	arr[2] = vIsurCd ;
            //CopyDataSet( dts_Delistdetail , param_dts_isu) ;
        	CopyDataSet( dts_DsclMst, param_dts_mst) ;
        	CopyDataSet( dts_DsclDtl, param_dts2) ;
        	return arr.length;
        }
         */
        // fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3,  param_dts_mst_eng, param_dts_dtl_eng) {
        scwin.getPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3, param_dts4, param_dts_isu_eng, param_dts_mst_eng, param_dts_dtl_eng, param_dts_dtl_all_eng, param_dts_rel_eng) {
            if (js_market === "2") {
                arr[0] = "70764";
            } else {
                arr[0] = "32006";
            }
            arr[1] = vBzProcsNo;
            arr[2] = scwin.vIsurCd;
            $c.stf.copyDataSet(dts_DsclMst, param_dts_mst);
            $c.stf.copyDataSet(dts_DsclDtl, param_dts2);
            $c.stf.copyDataSet(dts_DsclMst_Eng, param_dts_mst_eng);
            $c.stf.copyDataSet(dts_DsclDtl_Eng, param_dts_dtl_eng);
            return arr.length;
        };
    } else if (rsnKey === "141" || rsnKey === "130") {
        // 변경상장 141, 추가상장 130
        const sbmOptions = {
            id : "sbm_dts_DsclMst",
            action : "/Listing.do",
            ref : "",
            target : "dts_DsclMst=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions2 = {
            id : "sbm_dts_DsclDtl",
            action : "/Listing.do",
            ref : "",
            target : "dts_DsclDtl=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        /* 2009.06.03 영문공시 추가 */
        const sbmOptions3 = {
            id : "sbm_dts_DsclMst_Eng",
            action : "/Listing.do",
            ref : "",
            target : "dts_DsclMst_Eng=body.content",
            isProcessMsg : false
        };

        const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
        // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions4 = {
            id : "sbm_dts_DsclDtl_Eng",
            action : "/Listing.do",
            ref : "",
            target : "dts_DsclDtl_Eng=body.content",
            isProcessMsg : false
        };

        const sbmRtn4 = await $c.sbm.executeDynamic(sbmOptions4);
        // TODO Stage2: sbmRtn4 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        if (rsnKey === "141") {
            /*
            fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
            	arr[0] = "70763";
            	arr[1] = vBzProcsNo ;
            	arr[2] = vIsurCd ;
                //CopyDataSet( dts_Delistdetail , param_dts_isu) ;
            	CopyDataSet( dts_DsclMst, param_dts_mst) ;
            	CopyDataSet( dts_DsclDtl, param_dts2) ;
            	return arr.length;
            }
             */
            // fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3,  param_dts_mst_eng, param_dts_dtl_eng) {
            scwin.getPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3, param_dts4, param_dts_isu_eng, param_dts_mst_eng, param_dts_dtl_eng, param_dts_dtl_all_eng, param_dts_rel_eng) {
                if (js_market === "2") {
                    arr[0] = "70763";
                } else {
                    arr[0] = "32004"; // 코넥스 변경상장

                }
                arr[1] = vBzProcsNo;
                arr[2] = scwin.vIsurCd;
                $c.stf.copyDataSet(dts_DsclMst, param_dts_mst);
                $c.stf.copyDataSet(dts_DsclDtl, param_dts2);
                $c.stf.copyDataSet(dts_DsclMst_Eng, param_dts_mst_eng);
                $c.stf.copyDataSet(dts_DsclDtl_Eng, param_dts_dtl_eng);
                return arr.length;
            };
        } else if (rsnKey === "130") {
            /*
            fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
            	arr[0] = "70791";
            	arr[1] = vBzProcsNo ;
            	arr[2] = vIsurCd ;
                //CopyDataSet( dts_Delistdetail , param_dts_isu) ;
            	CopyDataSet( dts_DsclMst, param_dts_mst) ;
            	CopyDataSet( dts_DsclDtl, param_dts2) ;
            	return arr.length;
            }
             */
            // fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3,  param_dts_mst_eng, param_dts_dtl_eng) {
            scwin.getPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3, param_dts4, param_dts_isu_eng, param_dts_mst_eng, param_dts_dtl_eng, param_dts_dtl_all_eng, param_dts_rel_eng) {
                if (js_market === "2") {
                    arr[0] = "70791";
                } else {
                    arr[0] = "32003"; // 코넥스 추가상장

                }
                arr[1] = vBzProcsNo;
                arr[2] = scwin.vIsurCd;
                $c.stf.copyDataSet(dts_DsclMst, param_dts_mst);
                $c.stf.copyDataSet(dts_DsclDtl, param_dts2);
                $c.stf.copyDataSet(dts_DsclMst_Eng, param_dts_mst_eng);
                $c.stf.copyDataSet(dts_DsclDtl_Eng, param_dts_dtl_eng);
                return arr.length;
            };
        }
        /* 2009.05.22 영문공시 추가 끝 */
        /* 2009.07.01 영문공시 추가 - 추가상장(종목) : 국문,영문 */
    } else if (rsnKey === "100B") {
        // 추가상장
        // alert("추가상장(종목)");
        const sbmOptions = {
            id : "sbm_dts_DsclMst",
            action : "/Listing.do",
            ref : "",
            target : "dts_DsclMst=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        // 영문
        const sbmOptions2 = {
            id : "sbm_dts_DsclMst_Eng",
            action : "/Listing.do",
            ref : "",
            target : "dts_DsclMst_Eng=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        scwin.getPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3, param_dts4, param_dts_isu_eng, param_dts_mst_eng, param_dts_dtl_eng, param_dts_dtl_all_eng, param_dts_rel_eng) {
            if (js_market === "2") {
                arr[0] = "70762";
            } else {
                arr[0] = "32013"; // 코넥스 추가상장(종목)

            }
            arr[1] = vBzProcsNo;
            arr[2] = scwin.vIsurCd;
            $c.stf.copyDataSet(dts_DsclMst, param_dts_mst);
            $c.stf.copyDataSet(dts_DsclDtl, param_dts2);
            $c.stf.copyDataSet(dts_DsclMst_Eng, param_dts_mst_eng);
            $c.stf.copyDataSet(dts_DsclDtl_Eng, param_dts_dtl_eng);
            // alert(dts_DsclMst_Eng.Text);
            return arr.length;
        };
