/**
 * @method
 * @name getRsnCse
 * @description get Rsn Cse 처리
 * @param {*} strRsn strRsn
 * @returns {void}
 * @hidden N
 */
scwin.getRsnCse = function(strRsn) {
    const arr = [ // 상장업무구분코드,
        ["130", ["602", "603", "604", "605", "606", "607", "608", "611", "612", "613", "614", "615", "616", "617", "618", "619", "620", "621", "622", "623", "624", "625", "628", "629", "630", "631", "642", "644", "646", "647"]],
        // 추가상장(기타도 포함)
        ["141", ["609", "610", "626", "627", "632", "633", "648", "649", "699", "650", "625"]], // 변경상장 (632 무액면, 633 액면, 648 주식병합(무액면주식), 649 주식분할(무액면주식) 650주식소각625우선주의 보통주전환)
        ["148", ["643"]], // 상호변경
        ["141A", ["640", "641"]], // 액면변경
        ["100B", ["601"]]
    ];
    for (let i = 0; i < arr.length; i++) {
        for (let j = 0; j < arr[i][1].length; j++) {
            if (arr[i][1][j] === strRsn) {
                return arr[i][0];
            }
        }
    }
    return -1;
};
